ALTER TABLE trellis.models
    ADD COLUMN trusted_metadata jsonb,
    ADD COLUMN metadata_status text NOT NULL DEFAULT 'pending'
        CHECK(metadata_status IN ('ready','pending')),
    ADD COLUMN metadata_verified_at timestamptz,
    ADD COLUMN availability text NOT NULL DEFAULT 'unknown'
        CHECK(availability IN ('available','unavailable','unknown')),
    ADD COLUMN availability_checked_at timestamptz;
UPDATE trellis.models m SET trusted_metadata=p.document,metadata_status='ready',
    metadata_verified_at=(p.document->>'as_of')::date
FROM trellis_private.model_profiles p
WHERE m.id=p.id AND m.provider_id=p.document->>'provider_id'
    AND m.upstream_model_id=p.document->>'upstream_model_id'
    AND m.adapter_kind=m.provider_id;
UPDATE trellis.models SET enabled=false WHERE metadata_status<>'ready';
INSERT INTO trellis.models(id,provider_id,provider_name,adapter_kind,upstream_model_id,name,
    requires_api_key,supports_streaming,supports_tools,enabled,catalog_order,
    trusted_metadata,metadata_status,metadata_verified_at)
SELECT p.id,p.document->>'provider_id',
    CASE p.document->>'provider_id' WHEN 'openai' THEN 'OpenAI' ELSE 'Anthropic' END,
    p.document->>'provider_id',p.document->>'upstream_model_id',p.document->>'name',
    true,true,true,false,100+row_number() OVER(ORDER BY p.id),p.document,'ready',(p.document->>'as_of')::date
FROM trellis_private.model_profiles p ON CONFLICT(id) DO NOTHING;
ALTER TABLE trellis.models ADD CONSTRAINT enabled_models_are_ready
    CHECK(NOT enabled OR (metadata_status='ready' AND availability<>'unavailable'));

CREATE FUNCTION trellis_private.enforce_model_profile() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_document jsonb;
BEGIN
    IF NEW.metadata_status='ready' THEN
        SELECT document INTO v_document FROM trellis_private.model_profiles WHERE id=NEW.id;
        IF v_document IS NULL OR NEW.trusted_metadata IS DISTINCT FROM v_document
           OR NEW.provider_id IS DISTINCT FROM v_document->>'provider_id'
           OR NEW.upstream_model_id IS DISTINCT FROM v_document->>'upstream_model_id'
           OR NEW.adapter_kind IS DISTINCT FROM NEW.provider_id
           OR NEW.metadata_verified_at IS NULL OR NOT NEW.supports_streaming OR NOT NEW.supports_tools THEN
            RAISE EXCEPTION 'model has no matching verified profile' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.trusted_metadata IS NOT NULL OR NEW.metadata_verified_at IS NOT NULL THEN
        RAISE EXCEPTION 'pending model cannot claim trusted metadata' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION trellis_private.enforce_model_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER enforce_model_profile BEFORE INSERT OR UPDATE ON trellis.models
FOR EACH ROW EXECUTE FUNCTION trellis_private.enforce_model_profile();
DROP POLICY models_read ON trellis.models;
CREATE POLICY models_read ON trellis.models FOR SELECT TO authenticated
    USING ((SELECT auth.uid()) IS NOT NULL);
COMMIT;
